SELECT interval_code, (MINUTE(DATE_ADD(candle_open_time, INTERVAL CASE interval_code WHEN '1m' THEN 60 WHEN '5m' THEN 300 ELSE 3600 END SECOND))=0) AS hour_boundary, COUNT(*) AS n, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, DATE_ADD(candle_open_time, INTERVAL CASE interval_code WHEN '1m' THEN 60 WHEN '5m' THEN 300 ELSE 3600 END SECOND), generated_at))/1000) AS avg_ms, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, DATE_ADD(candle_open_time, INTERVAL CASE interval_code WHEN '1m' THEN 60 WHEN '5m' THEN 300 ELSE 3600 END SECOND), generated_at))/1000) AS max_ms, SUM(TIMESTAMPDIFF(MICROSECOND, DATE_ADD(candle_open_time, INTERVAL CASE interval_code WHEN '1m' THEN 60 WHEN '5m' THEN 300 ELSE 3600 END SECOND), generated_at) > 5000000) AS over_5s FROM crypto_ai.trade_signal WHERE generated_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 11:00:00' AND signal_mode='LIVE' GROUP BY interval_code, hour_boundary ORDER BY interval_code, hour_boundary;